import { describe, expect, it } from 'vitest';
import * as fs from 'fs';
import * as path from 'path';

const brandingDir = path.resolve(__dirname, '../../renderer/assets/branding');

/**
 * The browser once shipped only an SVG, so the window/taskbar icon and every
 * electron-builder target silently fell back to the default Electron icon.
 * These raster assets are generated by scripts/generate-icons.py; this test
 * fails the build if any of them go missing again.
 */
describe('branding assets', () => {
    it('ships the raster app icon PNG used by the window and linux packages', () => {
        const png = path.join(brandingDir, 'hoo-app-icon.png');
        expect(fs.existsSync(png)).toBe(true);
        const head = fs.readFileSync(png).subarray(0, 8);
        expect([...head]).toEqual([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
    });

    it('ships the windows .ico and macos .icns variants', () => {
        expect(fs.existsSync(path.join(brandingDir, 'hoo-app-icon.ico'))).toBe(true);
        expect(fs.existsSync(path.join(brandingDir, 'hoo-app-icon.icns'))).toBe(true);
    });

    it('ships the sized linux icon set including a 256px minimum', () => {
        for (const size of [16, 24, 32, 48, 64, 128, 256, 512]) {
            const sized = path.join(brandingDir, 'icons', `hoo-${size}.png`);
            expect(fs.existsSync(sized)).toBe(true);
            expect(fs.statSync(sized).size).toBeGreaterThan(0);
        }
    });

    it('keeps the svg master that the icon pipeline renders from', () => {
        expect(fs.existsSync(path.join(brandingDir, 'hoo-app-icon.svg'))).toBe(true);
    });
});
